"""Independent identifier facts at raw CLI and public model admission boundaries."""

from __future__ import annotations

import dataclasses
import importlib
import json
import re
import sys
import unittest

from test_pipeline import REPOSITORY, SourceFixture, json_data, rust_string


# Fixed external vectors, not answers generated by the production checksum code.
# ORCID's identifier-structure guidance supplies the first three ORCID examples:
# https://support.orcid.org/hc/en-us/articles/360006897674-Structure-of-the-ORCID-Identifier
# The other current identifiers are the owner's reviewed project facts; the
# second ISNI is the example in ISO 27729:2024 section 4 / Annex A.
ORCID_VECTORS = (
    "0000-0002-1825-0097",
    "0000-0001-5109-3700",
    "0000-0002-1694-233X",
    "0009-0005-2713-9242",
)
ISNI_VECTORS = ("0000 0005 1802 960X", "1422 4586 3573 0476")


class IdentifierCliTests(SourceFixture):
    """The real source CLI must refuse a wrong checksum without inventing facts."""

    def set_identifier(self, key: str, value: str, status: str = "populated") -> None:
        """Edit exactly one owned source record, without production schema helpers."""
        entry = {"value": value, "status": status,
                 "source": "Independent identifier fixture", "reason": "Exact identifier control"}
        encoded = ", ".join(f"{name} = {json.dumps(text)}" for name, text in entry.items())
        line = f"{json.dumps(key)} = {{ {encoded} }}"
        text = self.record.read_text(encoding="utf-8")
        changed, count = re.subn(r"(?m)^" + re.escape(json.dumps(key)) + r"\s*=.*$",
                                 lambda _: line, text)
        self.assertEqual(count, 1)
        self.write_record(changed)

    def test_current_identifiers_reach_public_outputs_unchanged(self) -> None:
        self.generate()
        public = json_data(self.output / "metadata.json")["public_metadata"]
        rust = (self.output / "rust/product.rs").read_text(encoding="utf-8")
        self.assertEqual(public["project.author.orcid"], "0009-0005-2713-9242")
        self.assertEqual(public["project.author.isni"], "0000 0005 1802 960X")
        self.assertEqual(rust_string(rust, "AUTHOR_ORCID"), "0009-0005-2713-9242")
        self.assertEqual(rust_string(rust, "AUTHOR_ISNI"), "0000 0005 1802 960X")

    def test_bad_orcid_check_digit_is_rejected_before_publication(self) -> None:
        self.set_identifier("project.author.orcid", "0009-0005-2713-9243")
        self.require_rejection(self.cli("validate"))
        self.require_rejection(self.cli("generate", output=self.output))
        self.assertFalse(self.output.exists())

    def test_bad_isni_check_digit_is_rejected_before_publication(self) -> None:
        self.set_identifier("project.author.isni", "0000 0005 1802 9600")
        self.require_rejection(self.cli("validate"))
        self.require_rejection(self.cli("generate", output=self.output))
        self.assertFalse(self.output.exists())

    def test_official_orcid_vectors_include_leading_zero_and_x(self) -> None:
        for identifier in ORCID_VECTORS:
            with self.subTest(identifier=identifier):
                self.set_identifier("project.author.orcid", identifier)
                self.require_success(self.cli("validate"))

    def test_isni_known_answers_include_x_and_decimal_checks(self) -> None:
        for identifier in ISNI_VECTORS:
            with self.subTest(identifier=identifier):
                self.set_identifier("project.author.isni", identifier)
                self.require_success(self.cli("validate"))

    def test_canonical_identifier_spelling_is_not_normalized(self) -> None:
        cases = (
            ("project.author.orcid", " 0009-0005-2713-9242"),
            ("project.author.orcid", "https://orcid.org/0009-0005-2713-9242"),
            ("project.author.orcid", "0009000527139242"),
            ("project.author.orcid", "0000-0002-1694-233x"),
            ("project.author.orcid", "０009-0005-2713-9242"),
            ("project.author.isni", "000000051802960X"),
            ("project.author.isni", "0000-0005-1802-960X"),
            ("project.author.isni", "0000 0005 1802 960x"),
        )
        for key, identifier in cases:
            with self.subTest(key=key, identifier=identifier):
                self.write_record(self.original_record)
                self.set_identifier(key, identifier)
                self.require_rejection(self.cli("validate"))

    def test_unknown_identifiers_remain_empty_and_unpublished(self) -> None:
        for key in ("project.author.orcid", "project.author.isni"):
            self.set_identifier(key, "", "pending")
        self.generate()
        public = json_data(self.output / "metadata.json")["public_metadata"]
        self.assertNotIn("project.author.orcid", public)
        self.assertNotIn("project.author.isni", public)
        fields = {row["key"]: row for row in json_data(self.output / "field-register.json")["fields"]}
        for key in ("project.author.orcid", "project.author.isni"):
            self.assertEqual(fields[key]["value"], "")
            self.assertEqual(fields[key]["status"], "pending")


class IdentifierModelTests(SourceFixture):
    """A forged typed model crosses the same semantic gate as a source record."""

    @classmethod
    def setUpClass(cls) -> None:
        sys.path.insert(0, str(REPOSITORY))
        try:
            cls.contract = importlib.import_module("metadata.pipeline.contract")
            cls.generator = importlib.import_module("metadata.pipeline.generate")
        finally:
            sys.path.remove(str(REPOSITORY))

    def setUp(self) -> None:
        super().setUp()
        self.model = self.contract.load_metadata(self.root)

    def replace_identifier(self, key: str, value: str):
        """Forge a public immutable model without invoking source parsing first."""
        return dataclasses.replace(self.model, fields=tuple(
            dataclasses.replace(field, value=value) if field.key == key else field
            for field in self.model.fields))

    def test_healthy_model_is_admitted(self) -> None:
        self.contract.validate_model(self.model)

    def test_direct_model_cannot_bypass_orcid_checksum(self) -> None:
        model = self.replace_identifier("project.author.orcid", "0009-0005-2713-9243")
        with self.assertRaises(self.contract.MetadataError):
            self.contract.validate_model(model)

    def test_direct_model_cannot_bypass_isni_checksum(self) -> None:
        model = self.replace_identifier("project.author.isni", "0000 0005 1802 9600")
        with self.assertRaises(self.contract.MetadataError):
            self.contract.validate_model(model)

    def test_only_the_correct_check_character_is_accepted(self) -> None:
        for key, good in (("project.author.orcid", "0009-0005-2713-9242"),
                          ("project.author.isni", "0000 0005 1802 960X")):
            for check in "0123456789X":
                with self.subTest(key=key, check=check):
                    candidate = self.replace_identifier(key, good[:-1] + check)
                    if check == good[-1]:
                        self.contract.validate_model(candidate)
                    else:
                        with self.assertRaises(self.contract.MetadataError):
                            self.contract.validate_model(candidate)

    def test_public_generation_api_rechecks_identifiers(self) -> None:
        for key, bad in (("project.author.orcid", "0009-0005-2713-9243"),
                         ("project.author.isni", "0000 0005 1802 9600")):
            with self.subTest(key=key), self.assertRaises(self.contract.MetadataError):
                self.generator.build_outputs(self.replace_identifier(key, bad))


if __name__ == "__main__":
    unittest.main()
